            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def _cell_to_text(value: Any) -> str:
    if value is None:
        return ''
    if isinstance(value, bool):
        return str(value)
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    if isinstance(value, (datetime, date)):
        return value.isoformat()
    return ' '.join(str(value).split())


def xlsx_to_csv_text(data: bytes, max_rows: int = MAX_ROWS) -> str:
    """Convert the active sheet to CSV text, keeping sheet row numbers aligned."""
    from openpyxl import load_workbook
    workbook = load_workbook(io.BytesIO(data), read_only=True, data_only=True)
    try:
        sheet = workbook.active
        out = io.StringIO()
        writer = csv.writer(out)
        for index, row in enumerate(sheet.iter_rows(values_only=True), 1):
            if index > max_rows + 1:
                break
            writer.writerow([_cell_to_text(v) for v in row])
        return out.getvalue()
    finally:
        workbook.close()


def validate_uploaded_users(file_obj: BinaryIO, filename: str) -> dict[str, Any]:
    """Validate an uploaded .xlsx/.csv of new users.

    Returns {'valid_users': [...], 'invalid_rows': [{'row': n, 'errors': [...]}, ...]}.
    Every row is checked; row numbers match the spreadsheet (header is row 1).
    """
    ext = os.path.splitext(filename or '')[1].lower()
    data = file_obj.read()
    try:
        if ext == '.xlsx':
            text = xlsx_to_csv_text(data)
        elif ext == '.csv':
            text = data.decode('utf-8-sig')
        else:
            return {'valid_users': [], 'invalid_rows': [{'row': 0, 'errors': ['unsupported file type; use .xlsx or .csv']}]}
    except Exception:
        return {'valid_users': [], 'invalid_rows': [{'row': 0, 'errors': ['file could not be read']}]}
    valid, errors = import_users(text)
    return {'valid_users': valid, 'invalid_rows': errors}

